            for c1 in range(w):
                c2 = c1 + side_h + 1
                if c2 >= w:
                    continue

                if not all(grid[r1][c] == 2 and grid[r2][c] == 2
                           for c in range(c1, c2 + 1)):
                    continue
                if not all(grid[r][c1] == 2 and grid[r][c2] == 2
                           for r in range(r1, r2 + 1)):
